import { WithIconProps } from '@livingdesign/icons';
import { KeyboardEvent, ReactElement } from 'react';
/** Visual variant type for MenuTrigger */
export type MenuTriggerVariant = 'default' | 'filter';
export interface MenuTriggerProps {
    /** Trigger button ID */
    id?: string;
    /** Display text or selected value */
    displayText: string;
    /**
     * Visual variant of the trigger
     * - 'default': Standard select field style with border
     * - 'filter': Compact pill/chip style for filter controls
     * @default 'default'
     */
    variant?: MenuTriggerVariant;
    /** Whether the menu is open */
    isOpen: boolean;
    /** Whether the trigger is disabled */
    disabled?: boolean;
    /** Click handler */
    onClick: () => void;
    /** Keyboard event handler */
    onKeyDown?: (event: KeyboardEvent<HTMLButtonElement>) => void;
    /** ARIA label */
    'aria-label'?: string;
    /** ARIA labelledby */
    'aria-labelledby'?: string;
    /** ARIA describedby */
    'aria-describedby'?: string;
    /** Menu dropdown ID for aria-controls */
    menuId?: string;
    /** Test identifier */
    'data-testid'?: string;
    /** Additional CSS classes */
    className?: string;
    /** Show as placeholder style */
    showAsPlaceholder?: boolean;
    /** Optional badge value to display (will be formatted with colon and parentheses). Can be a count, status label, or any other supplementary information. */
    badge?: string | number | null;
    /** Optional leading icon (typically used with filter variant). Must be a Living Design icon component. Renders as 16x16 small icon. */
    leadingIcon?: ReactElement<WithIconProps>;
}
